-//   SOLUZIONE 2024-06-07 )
+	watch_des *w = &watch_state;
+
+	if (!w->v) {
+		flog(LOG_WARN, "watch: nessun watch installato");
+		c_abort_p();
+		return;
+	}
+
+	if (esecuzione->id != w->watcher_id) {
+		flog(LOG_WARN, "watch: processo non watcher");
+		c_abort_p();
+		return;
+	}
+
+	if (w->watched_waiting) {
+		des_proc *watched = rimozione_lista(w->watched_waiting);
+		esecuzione->contesto[I_RAX] = watched->new_watch_value;
+		w->old_value = watched->new_watch_value;
+		watched->puntatore = nullptr;
+		inserimento_lista(pronti, watched);
+	} else {
+		w->watcher_waiting = esecuzione;
+		esecuzione->puntatore = nullptr;
+		inspronti();
+	}
 }
